import 'dart:io';

import 'package:flutter/cupertino.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/svg.dart';

import '../../../models/isar/models/blockchain_data/v2/transaction_v2.dart';
import '../../../models/isar/models/isar_models.dart';
import '../../../models/isar/stack_theme.dart';
import '../../../providers/global/wallets_provider.dart';
import '../../../themes/theme_providers.dart';
import '../../../wallets/crypto_currency/crypto_currency.dart';

class TxIcon extends ConsumerWidget {
  const TxIcon({
    super.key,
    required this.transaction,
    required this.currentHeight,
    required this.coin,
  });

  final TransactionV2 transaction;
  final int currentHeight;
  final CryptoCurrency coin;

  static const Size size = Size(32, 32);

  String _getAssetName(
    bool isCancelled,
    bool isReceived,
    bool isPending,
    IThemeAssets assets,
  ) {
    if (isReceived) {
      if (isCancelled) {
        return assets.receiveCancelled;
      }
      if (isPending) {
        return assets.receivePending;
      }
      return assets.receive;
    } else {
      if (isCancelled) {
        return assets.sendCancelled;
      }
      if (isPending) {
        return assets.sendPending;
      }
      return assets.send;
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final tx = transaction;
    final txIsReceived = tx.type == TransactionType.incoming;
    final currency = ref.watch(pWallets).getWallet(tx.walletId).cryptoCurrency;
    final isPending = !tx.isConfirmed(
      currentHeight,
      currency.minConfirms,
      currency.minCoinbaseConfirms,
    );
    final assetName =
        PivxTxKind.iconAsset(tx.pivxKind, pending: isPending) ??
        _getAssetName(
          false,
          txIsReceived,
          isPending,
          ref.watch(themeAssetsProvider),
        );

    return SizedBox(
      width: size.width,
      height: size.height,
      child: Center(
        // if it starts with "assets" we assume its local
        // TODO: a more thorough check
        child: assetName.startsWith("assets")
            ? SvgPicture.asset(
                assetName,
                width: size.width,
                height: size.height,
              )
            : SvgPicture.file(
                File(
                  assetName,
                ),
                width: size.width,
                height: size.height,
              ),
      ),
    );
  }
}
